update public.characters set current_class = 'Warrior' where current_class = 'Warrior R1';
update public.characters set current_class = 'Duelist' where current_class = 'Duelist R2';
update public.characters set current_class = 'Berserker' where current_class = 'Berserker R3';
update public.characters set current_class = 'Conqueror' where current_class = 'Conqueror R4';
update public.characters set rank_tier = 'Elite I' where rank_tier in ('Rookie III / Hero I', 'Apprentice III');
update public.characters set mirage_tower = 'F85' where mirage_tower in ('Moonlit Forest F85', 'Fantasia Ascent F85');
update public.characters set custom_question = replace(replace(custom_question, 'Morning Stars', 'Dawnium'), '4 Active', '4 Techniques') where custom_question like '%Morning Stars%' or custom_question like '%4 Active%';
update public.characters set daily_buy_pattern = replace(daily_buy_pattern, 'gold mine', 'Gilded Depths') where daily_buy_pattern like '%gold mine%';
update public.characters set pet_status = 'Saving Bond Trinkets and Summon Crystals (60 Summon Crystals for a Mythic Fantomon)' where pet_status like '%bond strings%' or pet_status like '%miracle pet%';
update public.characters set relic_progress = 'Farming Rare relics before Cinder Ridge; Dark and Fire' where relic_progress like '%blue relics%';
update public.characters set shop_routine = 'Vendor Booth: 2-3 refreshes for discounted Stone and Wood' where shop_routine like '%General shop%';
update public.character_skill_slots set slot_kind = 'Technique' where slot_index <= 4 and slot_kind <> 'Technique';
update public.character_skill_slots set slot_kind = 'Charm' where slot_index >= 5 and slot_kind <> 'Charm';
update public.catalog_skills set en = 'Whirlwind Slash', cd = '1 Turn', element = 'Physical', description = 'Xoay kiếm 4 hit AoE (8 ô xung quanh). Trụ cột kích Hỏa Ấn và Hút Máu xuyên suốt R1-R3.' where id = 'r1_whirlwind';
